--- a/VisualMagick/installer/inc/version.isx
+++ b/VisualMagick/installer/inc/version.isx
@@ -10,5 +10,5 @@

 #define public MagickPackageName "GraphicsMagick"
 #define public MagickPackageVersion "1.4"
-#define public MagickPackageVersionAddendum ".020210323"
-#define public MagickPackageReleaseDate "snapshot-20210323"
+#define public MagickPackageVersionAddendum ".020210324"
